window.K3_QRAW.push.apply(window.K3_QRAW, [
  {"id": "kc|edu-principle|ep-06|知识点六|4", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点六：课程评价（重点：课程评价模式）", "no": 4, "q": "并多次组织学生座谈会，询问学生“课程中最喜欢的环节”“希望增加哪些内容”等问题。同时，评价者还邀请非遗传承人与家长代表参加评价会议，收集他们对课程的建议。最终，评价者结合各方反馈对课程进行调整。这种课程评价模式属于（　）", "opts": ["应答模式", "目标游离模式", "目标达成模式", "CIPP模式"], "a": 0, "exp": "此题考查课程评价的功能。课程评价的导向功能是指课程评价对实际教学活动具有定向引导的作用。受该校语文课程评价影响，教师围绕提升学生的文学鉴赏能力展开教学，体现了课程评价的导向功能。因此，答案选A。A.应答模式：强调评价应当从关注课程的所有人的需要出发，通过信息反馈，让方案结果满足大多数人的需要。题干中，评价者收集各方对课程的建议，并根据这些反馈对课程进行调整，体现了应答模式的特点。√B.目标游离模式：评价者应注意的是课程的实际效应，而不是其预期效应，评价的重点应从“课程计划预期的效果”转向“课程计划实际的结果”。C.目标达成模式：教育的目的在于改变学生的行为，评价就是要衡量学生行为实际发生变化的程度，通过预先设定的行为目标设计课程、评价课程。深联系微信193163788日D.CIPP模式：包括背景评价、输人评价、过程评价和结果评价。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 157}},
  {"id": "kc|edu-principle|ep-06|知识点六|5", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点六：课程评价（重点：课程评价模式）", "no": 5, "q": "CIPP模式突出形成性评价和综合性评价的功能，几乎对课程开发的全程都可以评价。其中，在课程实施的学校中了解周边资源应属于（　）", "opts": ["背景评价", "输人评价", "过程评价", "结果评价"], "a": 0, "exp": "此题考查CIPP模式。A.背景评价：分析环境、问题、需求、机会、资源。题干中的“在课程实施的学校中了解周边资源”与背景评价相符。√B.输人评价：在背景评价的基础上，对达到目标所需的条件、资源以及各备选方案的相对优点所做的评价，实质上是对方案的可行性和效用性进行评价。C.过程评价：对方案实施的过程进行连续不断的监督、检查和反馈。D.结果评价：对目标达到的程度所做的评价，包括测量、判断、解释方案的成就。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 157}},
  {"id": "kc|edu-principle|ep-06|知识点七|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点七：新课程改革", "no": 1, "q": "我国普通高中课程改革由学习领域、科目和模块三个层次构成。这属于（　）", "opts": ["课程管理的改革", "课程结构的改革", "课程内容的改革", "课程组织的改革"], "a": 1, "exp": "此题考查课程改革。我国普通高中课程由学习领域、科目、模块三个层次构成，这是对课程结构的改革，与课程内容、课程管理无关。课程组织广义上强调的是对课程整个开发过程的描述，狭义上强调的是课程内容如何组织和安排，与题干不符。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 158}},
  {"id": "kc|edu-principle|ep-06|知识点七|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点七：新课程改革", "no": 2, "q": "以下关于综合实践活动课程的说法，正确的是（　）", "opts": ["以小组合作为主，不鼓励学生独立实践", "考虑到小学生年龄较小，可以暂缓设置", "主张发展学生的自主性，提升综合能力", "以学生的课程考试成绩为唯一评价标准"], "a": 2, "exp": "此题考查综合实践活动课程。A.修改：综合实践活动课程既鼓励小组合作、集体活动，也支持学生独立实践。B.修改：综合实践活动课程从小学至高中都要设置，属于必修课程。C.综合实践活动课程主张发展学生的自主性和探究性，提升学生的综合能力。√D.修改：综合实践活动课程的评价通过成果展示、学生自评互评等形式进行，不以考试成绩为唯一评价标准。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 158}},
  {"id": "kc|edu-principle|ep-06|知识点七|3", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点七：新课程改革", "no": 3, "q": "中国学生发展核心素养的三个方面不包括（　）", "opts": ["文化基础", "自主发展", "社会参与", "健康生活"], "a": 3, "exp": "此题考查核心素养。中国学生发展核心素养，以“全面发展的人”为核心，分为文化基础、自主发展、社会参与三个方面，不包括健康生活。此题为选非题，因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 158}},
  {"id": "kc|edu-principle|ep-06|知识点七|4", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点七：新课程改革", "no": 4, "q": "20世纪，世界各国的课程改革呈现新的趋势，其趋势不包括（　）", "opts": ["注重培养学生的思维力、创造力与探索精神", "课程评价更加强调过程性与全程性", "课程实施从创生取向走向了忠实取向", "学生的学习方式更加具有主动性与探究性"], "a": 2, "exp": "此题考查课程改革的趋势。课程实施从忠实取向走向了相互适应取向与创生取向。课程的创生取向是课程实施研究中的新兴取向。该取向认为，真正的课程是教师与学生联合创造的教育经验，课程实施本质上是在具体教育情境中创生新的教育经验的过程，即有的课程计划只是供这个经验创生过程选择的工具而已。此题为选非题，因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 158}},
  {"id": "kc|edu-principle|ep-06|知识点七|5", "bank": "kc", "subj": "edu-principle", "ch": "ep-06", "chName": "第六章 课程", "sec": "知识点七：新课程改革", "no": 5, "q": "下列关于综合实践活动课程与各类学科课程的关系，说法错误的是（　）", "opts": ["学科领域的知识可以在综合实践活动中延伸、综合、重组与提升", "综合实践活动中所获得的技能可以在各学科教学中拓展", "在某些情况下综合实践活动可以和学科教学打通进行", "综合实践活动课程与学科课程是一种主导与从属的关系"], "a": 3, "exp": "此题考查综合实践活动课程。A、B、C选项说法正确。D选项的错误之处在于：综合实践活动课程与各类学科课程既相对独立，又紧密联系，形成有机整体。二者不是主导与从属的关系。此题为选非题，因此，答案选D。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 158}},
  {"id": "kc|edu-principle|ep-07|知识点一|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点一：教学及相关概念", "no": 1, "q": "以下正确反映教学和智育之间关系的命题是（　）", "opts": ["教学是智育的唯一途径", "教学是智育的主要途径", "智育是教学的唯一任务", "智育是教学的次要任务"], "a": 1, "exp": "此题考查教学与智育的关系。教学是智育的主要途径，但不是唯一途径，教学同时还是德育、美育、体育、劳动教育的途径，A选项错误，B选项正确。智育是教学的主要任务，但不是唯一任务，C、D选项错误。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 160}},
  {"id": "kc|edu-principle|ep-07|知识点一|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点一：教学及相关概念", "no": 2, "q": "关于教学的本质，以下哪种理解最为准确？（　）", "opts": ["教学是教师将知识与技能系统地传递给学生的过程，核心在于教师的讲授", "教学是教师有目的地引导学生主动学习，以促进其身心发展的双边交互的教育活动过程", "教学是学校课程计划的具体执行，完成了预设的课程内容，教学任务即告达成", "教学是师生围绕特定话题展开的随机对话与交流，目的是激发学生的即时兴趣"], "a": 1, "exp": "此题考查教学的本质。A.教师单向传递知识给学生，没有强调双边互动性，不符合现代教育理念。B.教学的要点包括：目的性、计划性、教师的引导性、学生的主体性、双边互动性、全面发展和个性发展。√C.将教学简化为机械执行既定计划，忽视了教学过程中学生的动态生成、情感体验以及实际发展效果。D.描述了某种可能的教学片段或非正式交流，但缺乏目的性、系统性和引导性，未能说明教学与其他对话活动的不同。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 160}},
  {"id": "kc|edu-principle|ep-07|知识点二|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点二：当代主要教学理论流派", "no": 1, "q": "以下倾向于废除直接教学、废除考试的教学理论流派是（　）", "opts": ["行为主义教学理论", "认知主义教学理论", "人本主义教学理论", "建构主义教学理论"], "a": 2, "exp": "此题考查人本主义教学理论。人本主义教学理论反对将教师和书本置于教学活动核心位置的做法，认为教学活动应把学生放在居中的位置，所有的教学活动不仅要服从“自我”的需要，而且要围着“自我”进行，重视自我评价，倾向于废除直接教学、废除考试。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 160}},
  {"id": "kc|edu-principle|ep-07|知识点二|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点二：当代主要教学理论流派", "no": 2, "q": "传统教育学流派代表人物赫尔巴特主张的“三中心”是指（　）", "opts": ["教师中心、教材中心和课堂中心", "儿童中心、经验中心和活动中心", "管理中心、活动中心和教学中心", "管理中心、服务中心和教学中心"], "a": 0, "exp": "此题考查传统教育学流派。赫尔巴特主张的“三中心”是指教师中心、教材中心和课堂中心。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 160}},
  {"id": "kc|edu-principle|ep-07|知识点二|3", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点二：当代主要教学理论流派", "no": 3, "q": "布鲁纳提倡发现教学方法，认为学生不是被动地接受知识，而是积极主动地在教师创造的学习情境中发现知识。这种教学方法属于（　）", "opts": ["行为主义教学理论．", "认知主义教学理论", "人本主义教学理论", "社会互动教学理论"], "a": 1, "exp": "此题考查当代主要教学理论流派。行为主义教学理论采用程序教学的方法，认知主义教学理论提倡发现教学方法，人本主义教学理论提倡有意义学习与非指导性学习，社会互动教学理论包括体现互动的所有方式方法。因此，答案选B。：", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 160}},
  {"id": "kc|edu-principle|ep-07|知识点二|4", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点二：当代主要教学理论流派", "no": 4, "q": "以下最强调在师生交往中加深学生对知识理解的教学理论是（　）", "opts": ["社会互动教学理论", "行为主义教学理论", "认知主义教学理论．", "人本主义教学理论"], "a": 0, "exp": "此题考查社会互动教学理论。A.社会互动教学理论最强调人与人的交往和互动对学习的推动作用。√B.行为主义教学理论重视相倚组织的形成，认为教学目标越具体精确越好。C.认知主义教学理论强调促进学习者内部认知结构的形成或改组，提倡发现学习。D.人本主义教学理论认为，在教学中，教师应起到促进者的作用。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 160}},
  {"id": "kc|edu-principle|ep-07|知识点三|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点三：教学模式", "no": 1, "q": "“教学的根本目标在于尽可能地使学生牢固掌握科学内容，尽可能使学生成为自主且自动的思想家，使其日后能够独立地探索。”这种教学模式属于（　）", "opts": ["程序教学模式", "发现教学模式", "暗示教学模式", "范例教学模式"], "a": 1, "exp": "此题考查发现教学模式。发现教学模式是在教师的指导下，学生围绕某个问题，根据手中已有的学习资料，去慢慢地发现内容间的联系，获得表象背后的概念与原理。其教学目标是促进学生理智和思维的发展，培养学生的创造性思维能力与独立探索、解决问题的能力。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 161}},
  {"id": "kc|edu-principle|ep-07|知识点三|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点三：教学模式", "no": 2, "q": "“以学生为本”“让学生自发学习”“排除对学习者自身的威胁”的教学模式属于（　）", "opts": ["发展性教学模式", "发现教学模式", "非指导性教学模式．", "暗示教学模式"], "a": 2, "exp": "此题考查非指导性教学模式。非指导性教学模式的含义较少有“直接性、命令性、指示性”等特征，而带有较多的“不明示性、间接性、非命令性”等特征。这种自我评价使学生更能为自已的学习负起责任，从而更加主动、有效、持久地学习。非指导性教学的关键在于促进学生形成学习的良好心理氛围。罗杰斯将教师的作用看作“学习的促进者”，也可以说是协作者、伙伴或朋友，师生关系是真诚友爱的，非指导性教学体现了“以学生中心”的思想。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 161}},
  {"id": "kc|edu-principle|ep-07|知识点三|3", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点三：教学模式", "no": 3, "q": "情境陶冶式教学模式的理论基础是（　）", "opts": ["布卢姆的掌握教学法", "罗扎诺夫的暗示教学法", "布鲁纳的发现教学法", "巴班斯基的最优教学法"], "a": 1, "exp": "此题考查情境陶冶式教学模式的理论基础。抓住题干关键词“情境陶冶”即可判断正确答案为罗扎诺夫的暗示教学法。情境陶冶式教学模式是在吸取了罗扎诺夫的暗示教学理论的基础上，使学生处在创设的教学情境中，运用学生的无意识心理活动和情感，加强有意识的、理性的学习活动的教学模式。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 161}},
  {"id": "kc|edu-principle|ep-07|知识点三|4", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点三：教学模式", "no": 4, "q": "“只要提供了足够的时间和帮助，每一个学生都能实现学习目标。”以下依据这种思想建构的教学模式是（　）", "opts": ["程序教学模式", "发现教学模式", "掌握学习教学模式", "非指导性教学模式"], "a": 2, "exp": "此题考查掌握学习教学模式。掌握学习教学模式以集体教学为基础，主张所有学生都能学好。布卢姆提出：“绝大多数学生都能学到学校所教的一切东西”，希望教师为掌握而教，学生为掌握而学，使每一个学生都能学好。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 161}},
  {"id": "kc|edu-principle|ep-07|知识点三|5", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点三：教学模式", "no": 5, "q": "某节小学美术课上，武老师和学生达成了“继承和发扬优秀传统文化是重要的”这一共识后，教师请学生们通过调查和讨论举例哪些内容属于传统文化，同学们完成了《传统文化记录表》，并证实了优秀传统文化的重要性。这一教学模式属于（　）", "opts": ["问题教学模式", "探究教学模式", "逆向设计教学模式·", "STEM教学模式"], "a": 2, "exp": "此题考查逆向设计教学模式。逆向设计教学模式是一种先确定学习的预期结果，再明确预期结果达到的证据，最后设计教学活动以发现证据的教学设计模式。题干中，武老师先和学生明确了要达成的共识，再请学生讨论举例，并证实了优秀传统文化的重要性，运用的是逆向设计教学模式。因此，答案选C。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 161}},
  {"id": "kc|edu-principle|ep-07|知识点三|6", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点三：教学模式", "no": 6, "q": "某教师设计了一堂课，以碳酸饮料为载体，让学生学习二氧化碳气体的检验方法与操作步骤，利用二氧化碳与水反应能生成碳酸的原理来制作碳酸饮料，并初步掌握压强、温度对气体溶解能力的影响。学生在进行了实验的分析、推理后，了解并掌握了六大营养素中的糖类以及添加剂的利与科学的使用方法。这一教学模式属于（　）", "opts": ["逆向设计教学模式", "项目探究教学模式", "问题教学模式", "掌握学习教学模式"], "a": 1, "exp": "此题考查项目探究教学模式。学生围绕“制作碳酸饮料”这一项目进行探究，在学习化学、物理学科原理的同时，进行实验操作，并结合推理，最终掌握知识。这是一种“做中学”，体现了项目探究教学模式。因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 161}},
  {"id": "kc|edu-principle|ep-07|知识点三|7", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点三：教学模式", "no": 7, "q": "某教师在教授物理学“力学”单元时，没有逐一讲解所有力学定律，而是精心选择“斜面滑块运动”这一现象进行深入剖析。他引导学生共同探究这一现象并掌握了力、加速度、摩擦力等核心概念，动”“汽车制动”等其他力学现象。这位教师采用的教学模式是（　）", "opts": ["程序教学模式", "发现教学模式", "范例教学模式", "非指导性教学模式"], "a": 2, "exp": "此题考查范例教学模式。A.程序教学模式强调小步子、积极反应、及时反馈、自定步调，与题干情境不符。B.发现教学模式强调创设问题情境、提出假设并验证，最后得出结论。题干中教师虽引导学生进行了探究，但核心是通过典型例子掌握原理和知识，更偏向范例教学，与题干情境不符。C.范例教学模式强调通过选择典型范例促进学生掌握原理、规律性的知识，便于学生广泛迁移和运用。迁移到“汽车制动”等其他现象，符合范例教学模式的特点。√D.非指导性教学模式强调“以学生为中心”的非指导性教学，侧重学生情感与人格发展，与题干情境不符。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 161}},
  {"id": "kc|edu-principle|ep-07|知识点三|8", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点三：教学模式", "no": 8, "q": "某校美院开展“××社区设计”，第一周进行课程的介绍和分组。第二、三、四周安排了理论学习、实地考察以及专家学者经验分享等环节，让学生对社区设计有了初步的认识。之后的三周，各小组积极沟通，在老师们的引导下，围绕选定的设计方向，从环境、经济、社会三个层面考量，输出了各组特色的创新设计方案。最后一周进行了展示与教师专家组点评。这一教学模式属于（　）", "opts": ["逆向设计教学模式", "项目探究教学模式", "STEM教学模式", "发现教学模式"], "a": 1, "exp": "此题考查项目探究教学模式。组完成任务并输出了各组特色的设计方案，最后对方案进行点评，这一系列活动体现了项目探究教学模式。因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 161}},
  {"id": "kc|edu-principle|ep-07|知识点三|9", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点三：教学模式", "no": 9, "q": "某中学地理课上，老师要求学生利用温度传感器监测校园不同区域的微气候，设计节能绿化工程方案，用数学建模分析数据，并撰写报告解释热岛效应的成因。该案例的核心教学模式是（　）", "opts": ["非指导性教学模式", "STEM教学模式", "逆向设计教学模式", "问题教学模式"], "a": 1, "exp": "此题考查STEM教学模式。A.非指导性教学模式强调学生自主探索，教师不进行干预，如何学习由学生自已决定。题干中教师明确提出了学习任务，所以不属于非指导性教学模式。B.STEM教学模式的重点是加强对学生科学素养、技术素养、工程素养和数学素养四个方面的综合性教育。题干中，使用温度传感器监测气候，要求掌握该项技术的应用方法，体现了技术素养的培养；设计节能绿化工程方案，体现了工程素养的培养；用数学建模分析数据，需要运用数学知识，体现了数学素养的培养；撰写报告解释热岛效应的成因，需要结合地理方面的知识，体现了科学素养的培养。这些环节共同体现了通过跨学科知识整合解决校园问题的教学模式。√C.逆向设计教学模式是先确定学习的预期结果，再明确预期结果达到的证据，最后设计教学活动以发现证据，与题干所述不符。D.问题教学模式是依据教材内容，设计问题，激发学生学习的兴趣，让学生在解决问题的思维活动中掌握知识、发展智力，培养学生分析、解决问题的能力，与题干所述不符。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 161}},
  {"id": "kc|edu-principle|ep-07|知识点三|10", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点三：教学模式", "no": 10, "q": "一共，，中一一，★块的练习并达到80%以上的正确率，才能进人下一模块。每做完一道题，系统会立即反馈正确答案和解析，并根据错误情况提供相似题目以便学生巩固练习。这种教学方式符合（、：）.（　）", "opts": ["发现教学模式", "程序教学模式", "非指导性教学模式", "范例教学模式"], "a": 1, "exp": "此题考查程序教学模式。A.发现教学模式强调学生自主探究，而非直接接受现成结论，与题干所述不符。B.程序教学模式的核心特征是将知识分解为一系列小步骤，学生按顺序逐步学习，前一步达标后才能进人下一步；学习过程中提供即时反馈；通过强化练习巩固知识，允许学生按自身节奏推进。题干描述的教学方式完全符合程序教学模式的核心特征。√C.非指导性教学模式以学生为中心，教师是促进者与激励者，而非具体学习内容的引导者，如何学习由学生自己决定，与题干所述不符。D.范例教学模式运用精选的范例作为教学内容，使学生掌握一般的、具有普遍意义的知识，与题干所述不符。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 162}},
  {"id": "kc|edu-principle|ep-07|知识点三|11", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点三：教学模式", "no": 11, "q": "围绕“是什么导致了城市空气质量的恶化？作为学生，我们能为改善身边空气做些什么？”等一系列问体现了（　）", "opts": ["逆向设计教学模式", "项目探究教学模式．", "问题教学模式", "掌握学习教学模式"], "a": 2, "exp": "此题考查问题教学模式。A.逆向设计教学模式强调先确定学习的预期结果，再明确预期结果达到的证据，最后设计教学活动以发现证据，注重目标的先导性，与题干情境不符。B.项目探究教学模式通常围绕一个相对独立的项目展开，多阶段合作都需要学生负责，涉及信息收集、方案设计、项目实施及评价等环节，与题干情境不符。C.问题教学模式通常以问题为出发点，围绕问题的提出、讨论、解决展开教学，强调学生在教师的引导下掌握知识、发展能力，获得分析、解决问题的能力。题干中教师先展示图片进行对比，再提出问题，引导学生思考和讨论。教师的角色是引导者和支持者而非直接讲授者，符合问题教学的特点。√D.掌握学习教学模式强调以集体教学为基础，辅之以经常、及时的反馈，为学生提供所需的个别化帮助以及额外学习时间，从而使大多数学生达到教学目标，与题干情境不符。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 162}},
  {"id": "kc|edu-principle|ep-07|知识点四|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点四：教学过程与教学环节", "no": 1, "q": "学生除了认真学习书本知识，还应当在玩（游戏）中学、做中学、研（探究）中学、用中学、创中学，在劳动生产中学，在生活与交往中学，在各种实践活动中学。这体现了教学过程中应处理好（　）", "opts": ["间接经验与直接经验的关系", "掌握知识与培养思想品德的关系", "掌握知识与提高能力（智力）的关系", "智力因素与非智力因素的关系"], "a": 0, "exp": "此题考查教学过程中应处理好的几种关系。学习书本知识属于间接经验，在玩中学、做中学获得的知识属于直接经验，题干体现了教学过程中应处理好间接经验与直接经验的关系。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 162}},
  {"id": "kc|edu-principle|ep-07|知识点四|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点四：教学过程与教学环节", "no": 2, "q": "有人认为，“消极地对待儿童，机械地使儿童集合在一起，课程和教学法的划一。概括地说，重心是在儿童以外，重心在教师，在教科书..唯独不在儿童自已的直接的本能和活动”。这体现了其重视（　）", "opts": ["直接经验", "间接经验", "能力培养", "品德陶冶"], "a": 0, "exp": "此题考查杜威的教育观。动”，强调直接经验对儿童发展的重要作用。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 162}},
  {"id": "kc|edu-principle|ep-07|知识点四|3", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点四：教学过程与教学环节", "no": 3, "q": "掌握知识与发展智力二者之间存在着辩证关系，妥善处理好二者之间的关系是教师应具备的基本能力。关于掌握知识与发展智力的关系，下列表述不正确的是（　）", "opts": ["掌握知识是发展智力的内容和手段", "智力的发展是掌握知识的前提条件", "掌握知识与发展智力并非同步进行", "掌握知识与发展智力的统一是自然而然实现的"], "a": 3, "exp": "此题考查掌握知识与发展智力的关系。掌握知识是发展智力的内容、手段和基础，智力的发展是掌握知识的前提条件；掌握知识与发展智力并非同步进行，知识与技能的掌握并不完全导致智力提高。A、B、C选项说法正确。掌握知识与发展智力的统一不是自然而然实现的，只有当我们透彻地理解和创造性地应用知识时，才能使其有效地转化为能力，D选项说法错误。此题为选非题，因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 162}},
  {"id": "kc|edu-principle|ep-07|知识点四|4", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点四：教学过程与教学环节", "no": 4, "q": "某位老师认为：“我无论担任哪一门功课的老师，都会认清那门功课的目标，如国文课的目标是学习文字，养成良好的语言运用习惯。同时，我始终不忘各门功课都有一个总目标，那就是‘教育”——培养健全的公民。”这说明教学过程需要协调好（　）", "opts": ["智力因素与非智力因素的关系", "教师主导作用与学生主体作用的关系", "掌握知识与培养思想品德的关系", "掌握知识与提高能力的关系"], "a": 2, "exp": "此题考查教学过程中应处理好的几种关系。教学必须实现教书育人的功能。因此，答案选C。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 162}},
  {"id": "kc|edu-principle|ep-07|知识点四|5", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点四：教学过程与教学环节", "no": 5, "q": "教学工作的中心环节是（　）", "opts": ["备课", "上课", "个别辅导", "布置作业"], "a": 1, "exp": "此题考查教学工作的环节。上课是教学工作的中心环节，提高教学质量的关键是上好课。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 162}},
  {"id": "kc|edu-principle|ep-07|知识点四|6", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点四：教学过程与教学环节", "no": 6, "q": "评课是教学研究的重要环节。下列选项中，哪一项通常不被视为评价“一堂好课”的核心标准？（　）", "opts": ["教学目标明确具体，学生实际达成度高", "教学内容严谨准确，容量与难度适中", "课堂管理严格，学生整齐划一", "教学环节清晰流畅，学生思维活跃度高"], "a": 2, "exp": "此题考查教学工作的基本环节一上课。A、B、D选项均正确，C选项过度强调课堂的表面秩序。现代课堂评价更注重学生在有序环境中的个性化表达、合作探究与思维碰撞，“整齐划一”可能压抑课堂的生成性与学生主体性，因此不属于评价“二堂好课”的标准。此题为选非题，因此，答案选C。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 162}},
  {"id": "kc|edu-principle|ep-07|知识点五|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点五：教学设计", "no": 1, "q": "“教学活动的每个步骤、每个环节都将受到教学设计方案的约束和控制”说明教学设计具有（　）", "opts": ["统合性", "操作性", "创造性", "指导性"], "a": 3, "exp": "此题考查教学设计的特点。A.统合性强调系统整合各要素，与题干中控制每个步骤、环节不符。B.操作性强调方案具体可行，但题干侧重“约束”“控制”而非“具体执行步骤”。C.创造性强调设计的新颖独特，与题干“受约束和控制”的表述相悖。D.指导性强调教学设计方案对整个教学活动过程具有约束与控制的作用，体现了教学设计在实施中的指引、规范与导向功能，这正是指导性的核心含义。√", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 163}},
  {"id": "kc|edu-principle|ep-07|知识点五|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点五：教学设计", "no": 2, "q": "任何一个步骤都可以作为教学的起点，向前或向后，能够灵活推动教学的模式是（　）", "opts": ["系统分析模式", "史密斯一雷根模式", "目标模式", "过程模式"], "a": 3, "exp": "此题考查教学设计模式。过程模式由肯普提出，它与目标模式的主要区别在于其设计步骤是非直线型的。设计者依据教学的需要，可从整个设计过程中的任何一个步骤起步，向前或向后。它的特点是灵活、实用。因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 163}},
  {"id": "kc|edu-principle|ep-07|知识点六|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点六：教学组织形式", "no": 1, "q": "目前世界范围内使用最普遍和最基本的教学组织形式是（　）", "opts": ["分组教学制", "道尔顿制", "班级授课制", "特朗普制"], "a": 2, "exp": "此题考查班级授课制。班级授课制是目前世界范围内使用最普遍和最基本的教学组织形式。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 163}},
  {"id": "kc|edu-principle|ep-07|知识点六|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点六：教学组织形式", "no": 2, "q": "王老师事先录制了讲解函数概念和基本运算的视频，并上传到学习平台。学生在课前观看视频，完成在线练习和自我评估。课堂上，王老师通过小组讨论、合作探究等方式帮助学生深人理解和应用函数知识。这种教学组织形式是（　）", "opts": ["个别化教学", "分层教学", "走班制", "翻转课堂"], "a": 3, "exp": "此题考查翻转课堂。A.个别化教学：适应学生个别差异，可以一对一教学，也可以一对多教学。B.分层教学：学习水平相近的群体为一组，即分组教学中的能力分组。C.走班制：自由选课，走班上课。D.翻转课堂：课下学生依据教学视频进行自主学习，课上师生交流讨论，深化学习。√", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 163}},
  {"id": "kc|edu-principle|ep-07|知识点六|3", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点六：教学组织形式", "no": 3, "q": "按照学生的能力或学习成绩把他们分为水平不同的群体进行教学，这是（　）", "opts": ["特朗普制", "分组教学制", "道尔顿制", "班级授课制"], "a": 1, "exp": "此题考查分组教学制。A.特朗普制：把大班上课、小班讨论、个人自学结合在一起，以灵活的时间单位代替固定统一的上课时间。与题干所述不符。B.分组教学制：按学生的能力或学习成绩把他们分成不同的组，分别进行教学的一种教学组织形式。√深联系微信1931637888C.道尔顿制：教师每周进行有限的集体教学，然后指定学习内容，学生接受学习任务后，在各专业课堂自学，独立完成作业，接受教师考查，然后又接受新的学习任务。与题于所述不符。D.班级授课制：把一定数量的学生按照年龄与知识程度编成固定的班级，根据周课表和作息时间表，安排教师有计划地向全班学生上课的一种集体教学形式。与题干所述不符。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 163}},
  {"id": "kc|edu-principle|ep-07|知识点六|4", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点六：教学组织形式", "no": 4, "q": "依据不同层次学生的学情，李老师在教学设计中设立了不同难度的任务，引导学生达到学习目标，满足各个层次学生发展的需要。这种教学组织形式是（　）", "opts": ["小队教学", "小组合作学习", "个别化教学", "分层教学"], "a": 3, "exp": "此题考查分层教学。分层教学是教师根据学生现有的知识、能力水平和潜力倾向把学生科学地分成水平相近的群体并区别对待，其实质是尊重学生个别差异，使学生的个性特长得到充分发挥。与题干描述相符。因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 163}},
  {"id": "kc|edu-principle|ep-07|知识点六|5", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点六：教学组织形式", "no": 5, "q": "王老师让学生课前预习时，先在互联网上搜集查阅有关唐玄宗的事例，还通过直播方式指导学生如何查找、筛选和分享信息。第二天正式上课时，王老师请同学们分享自已查找的信息和看法。课上，王老师帮助同学们深化了对唐玄宗的人物评价，最后总结出评价一个历史人物的方法。这种教学组织形式是（　）", "opts": ["小队教学", "混合教学", "分层教学", "泛在学习"], "a": 1, "exp": "此题考查混合教学。学习逐渐引向“深度”学习。题干中，王老师请同学们“线上+线下”搜集相关资料，为在课堂上深度理解人物评价的方法奠定了基础。因此，答案选B。，", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 163}},
  {"id": "kc|edu-principle|ep-07|知识点六|6", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点六：教学组织形式", "no": 6, "q": "为了帮助城乡教师共享优质教学资源，某市教育局组织名师团队开发了系列学科微课，包含智能推荐的分层练习模块。这些教学资源通过移动端教育云平台向全市教师开放，支持碎片化学习，同时每月结合线下分层辅导的方式引导教师进行深度学习。这套教学资源应用模式体现的教学组织形式是）（　）", "opts": ["翻转课堂、混合教学、分层教学", "泛在学习、分组教学、翻转课堂", "混合教学、分层教学、泛在学习", "分层教学、翻转课堂、分组教学"], "a": 2, "exp": "此题考查教学组织形式。“，+“，（）（2）“分层练习”体现分层教学。（3）“移动端教育云平台向全市教师开放，支持碎片化学习”体现泛在学习。（4）翻转课堂需要完整的课前一课中活动链。题干中，线下分层辅导与微课学习不是每天都有的链条化的教学活动，如果多天使用微课学习，每月只有一次线下分层辅导，不符合翻转课堂的基本要求。因此，答案选C。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 163}},
  {"id": "kc|edu-principle|ep-07|知识点六|7", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点六：教学组织形式", "no": 7, "q": "下列分组教学类型与具体做法的匹配，不正确的是（　）", "opts": ["兴趣分组一把对机器人感兴趣的学生划为科创小组", "能力分组—根据期中考试成绩把学生分到C三个不同层次的班级中", "作业分组一同一班级内不同小组完成不同难度的实验报告", "异质分组一将不同性格特质的学生混合编人合作学习小组"], "a": 2, "exp": "此题考查现代教学组织形式的改革。A.兴趣分组是把有相同兴趣的学生划为一组，如科创小组是对机器人感兴趣的学生组成的小组。B.能力分组是按照能力（如学生成绩）水平分组，如根据考试成绩把学生分到A、B、C三个不同层次的班级中。C.修改：作业分组是根据学生的兴趣或任务分组，如A选项的科创小组。根据需要完成的作业或报告的难度分组属于能力分组。此题为选非题。√D.异质分组时，组内每个成员都具有差异性，如将不同性格特质的学生编人一组。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 163}},
  {"id": "kc|edu-principle|ep-07|知识点七|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点七：教学原则", "no": 1, "q": "一篇课文教完了，老师组织学生认读、默写、讲解词义、填词、造句，以及形近字、音近字、同音字、近义字比较辨析，这体现了（　）", "opts": ["系统性原则", "巩固性原则", "量力性原则", "理论联系实际原则"], "a": 1, "exp": "此题考查巩固性原则。教学原则总结表原则特点通过引导学生观察所学事物或教师语言的形象描述，形成对所学事物、过程的清晰表象，直观性原则使其正确理解书本知识并发展认识能力巩固性原则引导学生在理解的基础上牢固掌握知识和技能，长久记忆，并能根据需要迅速再现和运用因材施教原则从学生的实际情况和个性特点出发，有的放矢地进行有区别的教学理论联系实际原则教学要以学习基础知识为主导，从理论与实际的联系上理解知识，注重学以致用教师要对学生进行启发，而不是告诉学生现成的答案，促使学生在教师的引导下积极思启发性原则考，自觉地掌握科学知识，提高分析问题和解决问题的能力续表原则特点系统性原则依据学科知识的内在逻辑、学生能力发展水平和掌握知识的顺序循序渐进地进行教学量力性原则教学的内容、方法和进度要适合学生的身心发展水平，需要学生经过努力才能掌握思想性和科学性统一的原则教学要以马克思主义为指导，·教授学生科学知识，并对学生进行思想教育", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 164}},
  {"id": "kc|edu-principle|ep-07|知识点七|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点七：教学原则", "no": 2, "q": "语文课上，王老师带领同学们学习《画杨桃》这篇课文时，展示了真正的杨桃，同学们一下子就理解了“我”为什么将杨桃画成了五角星形状的东西。这一做法体现了（　）", "opts": ["巩固性原则", "直观性原则", "理论联系实际原则", "因材施教原则"], "a": 1, "exp": "此题考查直观性原则。依据知识点七第1题解析，王老师在讲《画杨桃》时，展示了真实的杨桃，借助直观工具，有助于学生理解课文，这体现了直观性原则。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 164}},
  {"id": "kc|edu-principle|ep-07|知识点七|3", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点七：教学原则", "no": 3, "q": "以下比较准确地体现了启发性教学原则的是（　）", "opts": ["各因其材", "学不等", "开而弗达", "人不知而不"], "a": 2, "exp": "此题考查启发性教学原则。A.“各因其材”说明教师教学是针对每个学生的不同情况区别对待的，体现了因材施教教学原则。B.“学不等”表明教学要遵循学生的心理发展特点，不能超越次第，要循序渐进，体现了系统性教学原则。C.“开而弗达”说明教学要启发学生而不是全部讲解，体现了启发性教学原则。√D.“人不知而不”是说一个人虽然不被别人理解，却没有产生愤怒或抱怨的情绪，体现了宽容的品质，未体现教学原则。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 164}},
  {"id": "kc|edu-principle|ep-07|知识点七|4", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点七：教学原则", "no": 4, "q": "赵老师在介绍放射性元素的相关知识时，分享了居里夫人从沥青铀矿残渣中分离出镭元素的事迹，（　）", "opts": ["理论联系实际原则", "思想性和科学性统一的原则", "巩固性原则", "系统性原则"], "a": 1, "exp": "此题考查思想性和科学性统一的原则。依据知识点七第1题解析，题干中，赵老师介绍放射性元素的相关知识，是科学性的体现；赵老师分享居里夫人的故事，引导学生感受科学家坚持探索的精神，是思想性的体现。因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 164}},
  {"id": "kc|edu-principle|ep-07|知识点八|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点八：教学方法", "no": 1, "q": "在教学中教师通过指导学生运用一定的仪器设备进行独立实验作业而获得知识和技能的方法是（　）", "opts": ["练习法", "演示法", "实习作业法", "实验法"], "a": 3, "exp": "此题考查教学方法。教学方法总结表方法特点讲授法教师通过语言系统连贯地向学生传授知识，促进学生智能和品德发展教师向学生提出问题，要求学生回答，通过问答的形式引导学生获取或巩固知识谈话法学生在教师指导下为解决特定问题而进行探讨，以辨明是非、获取知识、锻炼思维和独立思考能力讨论法续表特点方法在教师指导下，学生运用仪器设备进行独立的实验作业，以获得知识或验证知识实验法学生在教师指导下进行学科实践活动，以培养学生专业操作能力实习法演示法教师向学生展示各种直观教具或示范实验等，使学生认识事物、获得知识或巩固知识练习法学生在教师指导下运用知识反复完成一定的操作，以形成技能、技巧参观法组织学生到特定场所观察、接触客观事物或现象以获得新知识，或巩固、验证所学知识自学辅导法以学生自学为主、教师辅导为辅角色扮演法学生在教师的指导下，通过扮演角色而获得情绪体验情境模拟法教师在课堂上创设一定的场景，指导学生进行模拟活动，完成特定情境任务，解决特定问题依据以上总结，因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 164}},
  {"id": "kc|edu-principle|ep-07|知识点八|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点八：教学方法", "no": 2, "q": "教师通过语言系统连贯地向学生传授知识、表达情感和价值观念的教学方法是（　）", "opts": ["练习法A演示法在一堂化学课上，张老师运用分子模型和挂图，帮助学生认识乙醛的分子结构。张老师采用的教学方法是（）", "讲授法演示法", "谈话法实习作业法", "陶冶法实验法"], "a": 1, "exp": "此题考查教学方法。依据知识点八第1题解析，张老师展示模型和挂图，运用的教学方法是演示法。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 164}},
  {"id": "kc|edu-principle|ep-07|知识点八|3", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点八：教学方法", "no": 3, "q": "班级里有个别同学喜欢告小状，老师想通过模拟的方式让同学们分别来扮演老师和学生，通过角色互换来让同学们自己认识到应不应该告小状，后来班级再也未出现过告小状的情况。这种教学方法是）（　）", "opts": ["谈话法", "团体公正法", "角色扮演法", "移情"], "a": 2, "exp": "此题考查教学方法。状。这一过程侧重情感体验，符合角色扮演法的特点。依据知识点八第1题解析，因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 164}},
  {"id": "kc|edu-principle|ep-07|知识点八|4", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点八：教学方法", "no": 4, "q": "学生在学习美国北方中央地区时，老师让学生在一幅绘有自然特征和天然资源但没有地名的地图上，找出这个地区主要城市的位置。结果，在课堂争论中，学生很快提出了许多有关城市建设要求的似乎合理的理论：水运理论，把芝加哥放在三个湖的汇合处；矿藏资源理论，把芝加哥放在默萨比山脉附近；食品供应理论，把一个大城市放在艾奥瓦的肥沃土地上等。这种教学过程体现了（）的魅力。（　）", "opts": ["发现法和讨论法", "练习法和讨论法", "讲授法和讨论法", "演示法和练习法"], "a": 0, "exp": "此题考查教学方法。在课堂上的争论中，同学们提出了各自的看法，体现了讨论法；在讨论中提出了各种新的理论，体现了发现法。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 164}},
  {"id": "kc|edu-principle|ep-07|知识点八|5", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点八：教学方法", "no": 5, "q": "美术课上，杨老师先在黑板上示范了如何勾勒人物轮廓、描绘五官细节，然后让学生选择自已喜欢的人物进行绘画，并及时给予学生指导和反馈。绘画结束后，杨老师组织学生互相观赏、评价作品。这堂课使用的教学方法有（　）", "opts": ["讲授法、演示法、讨论法", "讲授法、练习法、参观法", "演示法、练习法、参观法", "演示法、练习法、讨论法"], "a": 3, "exp": "此题考查教学方法。知识和技能，属于演示法；“让学生选择自已喜欢的人物进行绘画”是学生通过实际动手练习来巩固所学的人物肖像绘画技巧，属于练习法；“绘画结束后，杨老师组织学生互相观赏、评价作品”则是学生之间通过交流、讨论来分享看法和意见，属于讨论法。因此，答案选D。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 165}},
  {"id": "kc|edu-principle|ep-07|知识点八|6", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点八：教学方法", "no": 6, "q": "在《雨的诉说》一课中，教师让学生自由发言，尝试以雨的口吻阐述处于不同季节、不同环境时的心理活动。该教师采用的教学方法是（．（　）", "opts": ["讨论法", "实验法", "情境模拟法", "角色扮演法"], "a": 3, "exp": "此题考查教学方法。A.讨论法侧重学生之间的交流、辩论，与题干描述不符。B.实验法通常用于科学实践操作，与题干描述不符。C.情境模拟法强调创设真实情境让学生模拟某种活动的过程，如模拟开庭的整个过程。此方法侧重参与活动的过程和步骤，不侧重所塑造的人物角色的心理。与题干描述不符。D.角色扮演法更突出体会角色的情绪情感等心理因素。题干中，“以雨的口吻”即要学生扮演“雨”这一角色，并体会“雨”的心理活动。√", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 165}},
  {"id": "kc|edu-principle|ep-07|知识点九|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点九：教学评价及其改革", "no": 1, "q": "某教师把班级里每一位同学这一学期的优秀字帖、高分答案，以及各种体现学生进步的作品等都收集了起来，并在期末设置了一个展板张贴展示，请同学们相互欣赏。这种学业成就评价方式属于（　）", "opts": ["诊断性评价", "纸笔测验", "表现性评价", "档案袋评价"], "a": 3, "exp": "此题考查学业成就评价。学业成就评价主要有三种类型：纸笔测验、表现性评价和档案袋评价。档案袋评价是指由学生在教师的指导下收集起来的，可以反映学生的努力情况、进步情况、学习成就等的一系列学习作品的汇集，符合", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 165}},
  {"id": "kc|edu-principle|ep-07|知识点九|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点九：教学评价及其改革", "no": 2, "q": "对于学生而言，无论是肯定性的教学评价，还是恰当的否定性评价，都有利于调动学生学习的积极性和参与性，促进学生及时改正错误，提高自身的学习成绩和学习能力。这属于教学评价的（　）", "opts": ["导向功能", "诊断功能", "激励功能", "修正功能"], "a": 2, "exp": "此题考查教学评价的功能。在教学中，恰当的教学评价易激发学生的学习动机，提升学生学习的效果。题干体现的是教学评价的激励功能。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 165}},
  {"id": "kc|edu-principle|ep-07|知识点九|3", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点九：教学评价及其改革", "no": 3, "q": "暑假开始，某校美术老师请同学们设计一件衣服，这种评价方式属于（　）", "opts": ["诊断性评价", "终结性评价", "扩展型表现性任务", "限制型表现性任务"], "a": 2, "exp": "此题考查学业成就评价。扩展型表现性任务没有具体的限制，给予学生高度的自由。在这一过程中，学生可以自由展示他们选择、分析、综合和评价各种信息的能力，以及对探究结果的判断、组织和深层次的加工能力。题干中，教师请同学们设计一件衣服，让学生自由进行，并未做过多限制，所以是扩展型表现性任务。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 165}},
  {"id": "kc|edu-principle|ep-07|知识点九|4", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点九：教学评价及其改革", "no": 4, "q": "学完《静夜思》后，教师点评了学生的《静夜思》朗读表演。关于教师的评价方式，下列说法不正确的是（　）", "opts": ["属于表现性评价，评分具有主观性", "属于外显性的评价方式", "属于注重过程的评价", "比纸笔测验更优越"], "a": 3, "exp": "此题考查学业成就评价。A.表现性评价是指通过客观测验以外的行动、表演、展示、操作、写作等更真实的表现来评价学生的口头表达能力、文字表达能力、思维能力、创造能力、实践能力的评价方法。题干中，教师评价学生的《静夜思》朗读表演，属于表现性评价，评分具有主观性。B：外显性与内隐性相对，如果纸笔测验是内隐性的评价方式，那么，表现性评价方式就是外显性的。C.题干中，教师及时点评学生的朗读，注重学生在任务完成过程中的表现，是注重过程的评价。D.修改：纸笔测验实施方便，既经济又省时，评分也较为客观、迅速。但它不能全面考察被测试者的工作态度、品德修养、组织管理能力及口头表达能力等。表现性评价强调真实的任务情境，聚焦学生在任务中的表现，从而考查学生更加复杂、应用的能力。但并非所有学习目标的达成都适合表现性评价，且评分的主观性难以完全避免，开发和实施评价的成本高。二者各有优劣。此题为选非题。√", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 165}},
  {"id": "kc|edu-principle|ep-07|知识点九|5", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点九：教学评价及其改革", "no": 5, "q": "小丽数学考了89分，在全班同学中处于中间水平，小丽爸爸因此觉得小丽不够努力，此评价属于（　）", "opts": ["绝对性评价", "相对性评价", "个体内差异评价", "综合性评价"], "a": 1, "exp": "此题考查教学评价方式。相对性评价又称常模参照性评价，是用常模参照性测验对学生成绩进行评定。题干中，小丽在全班同学中处于中间水平，是通过和他人比较得出的评价，属于相对性评价。A、C、D选项均与题干不符。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 165}},
  {"id": "kc|edu-principle|ep-07|知识点九|6", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点九：教学评价及其改革", "no": 6, "q": "布卢姆根据评价在教学活动中的不同作用，将其分为诊断性评价、形成性评价和终结性评价。下列关于三种教学评价的说法，正确的是（　）", "opts": ["形成性评价不可以量化", "终结性评价不可以质化", "形成性评价侧重质化", "终结性评价只能量化"], "a": 2, "exp": "此题考查教学评价方式。形成性评价侧重质化，但也可以量化，如老师采用书面试卷检验学生不同阶段的学习状况，A选项错误，C选项正确。终结性评价侧重量化，但也可以质化，如老师对学生本学期综合素质进行书面评价，B、D选项错误。因此，答案选C。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 165}},
  {"id": "kc|edu-principle|ep-07|知识点九|7", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点九：教学评价及其改革", "no": 7, "q": "某校在课程改革三年后，为系统评估毕业生在改革前后创新能力、实践能力等方面的发展情况，收集了学生课堂表现、学生作品等课程实施过程中的质性资料。该校采用的评价方法是（　）", "opts": ["诊断性评价、相对性评价和质性评价的结合", "终结性评价、个体内差异评价和质性评价的结合", "形成性评价、诊断性评价和量化评价的结合", "表现性评价、绝对性评价和量化评价的结合"], "a": 1, "exp": "此题考查教学评价的种类。（1）终结性评价是在一个大的学习阶段后对学生的学习结果进行的评价。该校在课程改革三年后评估毕业生的发展情况，属于终结性评价。（2）个体内差异评价是对被评价者横向或纵向的进步进行比较。题干中，系统评估毕业生在改革前后创新能力、实践能力等方面的发展情况，涉及对学生不同方面的比较，属于个体内差异评价。、（3）质性评价是通过描述、解释等方式来呈现评价结果。学校通过学生课堂表现、学生作品等课程实施过程中的质性资料进行评估，属于质性评价。综上，该校采用的评价方法是终结性评价、个体内差异评价和质性评价的结合。因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 165}},
  {"id": "kc|edu-principle|ep-07|知识点九|8", "bank": "kc", "subj": "edu-principle", "ch": "ep-07", "chName": "第七章 教学", "sec": "知识点九：教学评价及其改革", "no": 8, "q": "小明和小红为同班同学，他们人学时的生物测试成绩分别为60分和55分。经过一学期的学习，在本学期期末生物测试中，小明考了80分，小红考了75分。以下评价方式中，最符合增值性评价特点的是（　）", "opts": ["依据两人期末生物测试成绩是否达到优秀来评价", "依据两人期末生物测试成绩班级排名的变化来评价", "依据两人人学以来生物测试成绩的提升幅度来评价", "依据两人在生物课堂上的发言次数与实验操作准确性来评价"], "a": 2, "exp": "此题考查教学评价的种类。A.以固定的分数作为优秀的标准，判断两人期末生物测试成绩是否达到该标准，属于绝对性评价。深联系微信1931637日8日B.关注两人期末生物测试成绩班级排名的变化，强调的是与他人横向对比的结果，属于相对性评价。C.增值性评价的重点在于考量学生在一段时间内成绩的进步幅度，侧重个体自身成绩的纵向提升。该选项依据两人人学以来生物测试成绩的提升幅度来评价，符合增值性评价的特点。√D.以两人在生物课堂上的发言次数与实验操作准确性为评价依据，是对学生课堂表现和课程技能的评价，属于表现性评价。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 166}},
  {"id": "kc|edu-principle|ep-08|知识点一|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-08", "chName": "第八章 德育", "sec": "知识点一：德育概述", "no": 1, "q": "以下不属于我国学校德育内容的是（　）", "opts": ["世界观、人生观、价值观教育", "爱国主义、集体主义和社会主义教育", "社会主义公民意识教育、理想信念教育和民主法治教育", "民族精神、时代精神和文化素养教育"], "a": 3, "exp": "此题考查我国学校德育的基本内容。此题可用排除法作答，文化素养教育属于智育的内容，并非德育的任务，其他内容均属于德育范畴。此题为选非题，因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 168}},
  {"id": "kc|edu-principle|ep-08|知识点一|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-08", "chName": "第八章 德育", "sec": "知识点一：德育概述", "no": 2, "q": "现代德育区别于传统德育的重要标志是（　）", "opts": ["更强调道德知识的记忆", "更注重道德主体的理性选择与批判性思维", "更依赖家庭与宗族的教化", "更突出对权威的无条件服从"], "a": 1, "exp": "此题考查现代德育和传统德育的区别。A.该选项是传统德育的典型特征之一，即通过灌输、背诵道德教条（如经典、规范）来传递价值观，B.现代德育强调学生是道德建构的主体，注重培养其道德判断力、理性选择能力及对价值的批判性反思，而非被动接受规则。这是现代德育转向“主体性”“对话性”“发展性”的核心标志。√C.传统社会（尤其是宗法社会）中，德育主要通过家族伦理、习俗和长辈权威传递。现代德育虽重视家校合作，但更强调学校、社会、家庭多元共育，且注重公共理性与公民道德。D.传统德育常与权威主义结合（如对师长、经典、政治权威的服从），现代德育则倡导在尊重规则的基础上，培养自主、负责的道德主体，鼓励理性对话与民主参与。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 168}},
  {"id": "kc|edu-principle|ep-08|知识点一|3", "bank": "kc", "subj": "edu-principle", "ch": "ep-08", "chName": "第八章 德育", "sec": "知识点一：德育概述", "no": 3, "q": "为促进学生全面发展，顺应社会发展需要，落实立德树人根本任务，要对学生进行“三生教育”。“三生教育”是指（　）", "opts": ["生存教育、生成教育、生涯教育", "生存教育、生活教育、生命教育", "生存教育、生态教育、生命教育", "生存教育、生态教育、生成教育"], "a": 1, "exp": "此题考查德育内容。依据题干，“三生教育”主要是为了学生的发展。生存教育、生活教育、生命教育都是关于学生发展的教育。生态教育是关于保护环境的教育，不是关于人自身发展的教育，不符合题意。生成教育并不是一个被广泛认可的标准术语，人们常说的类似的专业词汇是生成式学习。生成式学习是指学习者通过主动建构知识（如总结、提问、类比等）来深化理解，而非被动接收信息，强调的是学习过程，不符合题意。生涯教育是一种旨在教会人如何进行生涯决策、规划人生、实现自我价值的综合性的教育活动，强调对生涯的整体规划，是关于人自身发展的教育，但与之相关的A选项不符合题意。因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 168}},
  {"id": "kc|edu-principle|ep-08|知识点二|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-08", "chName": "第八章 德育", "sec": "知识点二：德育模式", "no": 1, "q": "以下把道德情感的培养置于中心地位的德育模式是（　）", "opts": ["认知发展模式", "价值澄清模式", "体谅模式", "社会学习模式"], "a": 2, "exp": "此题考查体谅模式。在德育模式中，体谅模式把道德情感的培养置于中心地位。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 168}},
  {"id": "kc|edu-principle|ep-08|知识点二|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-08", "chName": "第八章 德育", "sec": "知识点二：德育模式", "no": 2, "q": "）认为道德教育的目的是培养道德推动者。（　）", "opts": ["社会学习模式", "社会行动模式", "体谅模式", "集体教育模式"], "a": 1, "exp": "此题考查社会行动模式。社会行动模式主张道德教育的目的是培养道德推动者。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 168}},
  {"id": "kc|edu-principle|ep-08|知识点二|3", "bank": "kc", "subj": "edu-principle", "ch": "ep-08", "chName": "第八章 德育", "sec": "知识点二：德育模式", "no": 3, "q": "“价值观最终是个人的，道德不是灌输的。”这一观点属于（　）", "opts": ["体谅模式", "价值澄清模式", "社会学习模式", "集体教育模式"], "a": 1, "exp": "此题考查价值澄清模式。价值澄清模式认为，价值观最终是个人的，道德不是灌输的。该模式认为世界上不存在统一的价值观，而且价值观是不能通过传授与灌输获得的。教师只能通过学习、分析、讨论、评价、反思等方法来帮助学生形成适合他们自己的价值观体系。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 168}},
  {"id": "kc|edu-principle|ep-08|知识点二|4", "bank": "kc", "subj": "edu-principle", "ch": "ep-08", "chName": "第八章 德育", "sec": "知识点二：德育模式", "no": 4, "q": "体谅模式的创立者围绕学生普遍感到困难的人际与社会交往问题，编制了一套《生命线丛书》情境教材，以发展青少年的人际技能。该丛书包含的三部分是（　）", "opts": ["《设身处地》《证明规则》《你会怎么办？》", "《敏感性》《证明规则》《你期望什么？》", "《敏感性》《你期望什么？》《你会怎么办？》", "《证明规则》《你期望什么？》《你会怎么办？》"], "a": 0, "exp": "此题考查体谅模式。《生命线丛书》由三部分组成，第一部分是《设身处地》，第二部分是《证明规则》，第三部分是《你会怎么办？》，循序渐进地向学生呈现越来越复杂的人际一社会情境。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 168}},
  {"id": "kc|edu-principle|ep-08|知识点二|5", "bank": "kc", "subj": "edu-principle", "ch": "ep-08", "chName": "第八章 德育", "sec": "知识点二：德育模式", "no": 5, "q": "三年级的小林平时爱看电视。某天，电视里放映了这样一则公益广告：一个小男孩在看见妈妈给外婆洗脚后，也端着一盆水要给妈妈洗脚，妈妈露出了欣慰的微笑。于是，小林晚上也学着小男孩的样子给妈妈端水洗脚。小林的行为体现的德育模式是（　）", "opts": ["体谅模式", "道德认知发展模式", "社会行动模式", "社会学习模式"], "a": 3, "exp": "此题考查社会学习模式。社会学习模式由美国心理学家班杜拉创建，该模式认为儿童通过观察和模仿他人的行为而获得知识、技能和行为习惯。因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 168}},
  {"id": "kc|edu-principle|ep-08|知识点二|6", "bank": "kc", "subj": "edu-principle", "ch": "ep-08", "chName": "第八章 德育", "sec": "知识点二：德育模式", "no": 6, "q": "一个学生在学校打架，老师找家长说：“您的孩子有打架骂人的坏习惯，您可得好好教育他。”家长当着老师的面问孩子：“谁教你骂人的？混蛋！谁教你打人来的？”接着就打了孩子一个耳光。该案例说明（　）", "opts": ["儿童会观察和模仿成人的行为，成人应做好言行举止的示范", "只有教师才可以成为学生的榜样", "学生只在品德方面会学习家长，把家长作为自已的榜样", "儿童选择榜样是随机的，他们选择榜样是没有条件的"], "a": 0, "exp": "此题考查社会学习模式。根据班杜拉的社会学习模式，儿童通过对榜样行为的观察和模仿可以学会良好行为，有时候也会学会攻击、骂人等不良行为，A选项正确。在道德与品德培养过程中，家长因其天然的优势，可以成为儿童的榜样，且不仅会在品德方面影响儿童，也会在待人接物等方面影响儿童，B、C选项错误。儿童一般会选择自已生命中的“重要人物”作为榜样，如家长、老师、偶像等，并不是没有标准的，D选项错误。因此，答案选A。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 169}},
  {"id": "kc|edu-principle|ep-08|知识点二|7", "bank": "kc", "subj": "edu-principle", "ch": "ep-08", "chName": "第八章 德育", "sec": "知识点二：德育模式", "no": 7, "q": "关于价值澄清模式，以下说法错误的是（　）", "opts": ["价值连续体法适用于大范围内对一些带有普遍意义的问题进行讨论", "价值单是指针对那些不善于交谈或不适合交谈和讨论的问题而采取的一种价值澄清手段", "澄清应答需要教师面对学生的回答做出一对一的评价", "澄清应答的主要目的是激发学生对自己价值观的思考"], "a": 2, "exp": "此题考查价值澄清模式。A.价值连续体法适用于大范围内对一些带有普遍意义的问题进行讨论。B.价值单是指针对那些不善于交谈或不适合交谈和讨论的问题而采取的一种价值澄清手段。它主要是以书写的形式促使学生思考，避免大范围讨论时学生易受干扰或受从众心理的影响。C.修改：澄清应答中教师面对学生的回答，不做出评价，在立场上始终保持中立。此题为选非题。√D.澄清应答主要在课堂中进行，即运用巧妙的应答技术，激发学生对自已价值观的思考。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 169}},
  {"id": "kc|edu-principle|ep-08|知识点二|8", "bank": "kc", "subj": "edu-principle", "ch": "ep-08", "chName": "第八章 德育", "sec": "知识点二：德育模式", "no": 8, "q": "下列关于道德认知发展模式的说法，错误的是（　）", "opts": ["尊重儿童道德发展的阶段和规律，有利于针对儿童的阶段发展特征实施德育", "注重儿童对道德的自我建构，强调儿童道德发展的主动性", "注重道德行为的研究，促进儿童道德水平的提升", "能让儿童在道德情境或矛盾冲突中逐渐提升道德水平"], "a": 2, "exp": "此题考查道德认知发展模式。A、B、D选项的说法均为道德认知发展模式的优点。道德认知发展模式过于强调道德认知，忽视了对道德情感和道德行为的研究，C选项说法错误。此题为选非题，因此，答案选C。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 169}},
  {"id": "kc|edu-principle|ep-08|知识点二|9", "bank": "kc", "subj": "edu-principle", "ch": "ep-08", "chName": "第八章 德育", "sec": "知识点二：德育模式", "no": 9, "q": "某教师在课堂上提出一个两难问题：“如果你在公交车上看到有老人上车，但自己此时身体不适，那么是否应该让座？”随后，教师引导学生分小组进行讨论，鼓励学生说出自已的选择及理由，教师最终不给出标准答案，而是让学生反思自己的价值观。该教师的做法体现了（　）", "opts": ["道德认知发展模式．", "价值澄清模式", "体谅模式", "社会学习模式"], "a": 1, "exp": "此题考查价值澄清模式。A.道德认知发展模式侧重通过道德推理来促进个体道德认知阶段的发展。题干所述内容并未涉及这一“阶段提升”的过程，排除该选项。B.价值澄清模式着眼于价值观教育，试图通过价值澄清的过程，帮助儿童减少价值观的混乱，并帮助儿童树立自己的价值观。题干中，教师引导学生自主讨论、反思，明确自已的价值观，符合该模式的特深联系微信193163788日征。√C.体谅模式以“情感体验”为核心，强调通过角色扮演、换位思考理解他人。题干更侧重理性讨论而非情感共鸣，排除该选项。D.社会学习模式强调观察模仿和行为强化（如榜样示范）。题干未涉及“行为训练”，排除该选项。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 169}},
  {"id": "kc|edu-principle|ep-08|知识点二|10", "bank": "kc", "subj": "edu-principle", "ch": "ep-08", "chName": "第八章 德育", "sec": "知识点二：德育模式", "no": 10, "q": "某班班会讨论“自习课违反纪律”这一问题时，甲同学认为必须严格执行班级规章制度，只要违反纪律，一律记名扣分，没有任何商量的余地；乙同学认为要先搞清楚违纪的原因，如果有特殊情况，可以免罚。根据科尔伯格的道德发展阶段理论，甲同学和乙同学分别处于（　）", "opts": ["第一阶段和第四阶段", "第二阶段和第三阶段", "第四阶段和第五阶段", "第五阶段和第六阶段"], "a": 2, "exp": "此题考查科尔伯格的道德发展阶段理论。甲同学认为，只要违反自习课纪律就要受到惩罚，说明他对团体规范绝对服从，认为规则是不可变动的。因而，可以判断他处于第四阶段一维护权威或秩序的定向阶段。乙同学认为，要先搞清楚违纪的原因，对于特殊情况可以免罚，说明他认识到规则应该根据实际情况进行调整，不再是机械地遵守规则。因而，可以判断他处于第五阶段一社会契约定向阶段。因此，答案选C。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 169}},
  {"id": "kc|edu-principle|ep-08|知识点二|11", "bank": "kc", "subj": "edu-principle", "ch": "ep-08", "chName": "第八章 德育", "sec": "知识点二：德育模式", "no": 11, "q": "马卡连柯“平行教育影响原则”的核心内涵是（　）", "opts": ["教师影响学生集体，再由集体去影响个人", "教师直接教育个人与教育集体，二者同时进行、相互促进", "教师的教育影响与学生的自我教育平行开展", "学校教育与家庭教育平行合作"], "a": 0, "exp": "此题考查马卡连柯的平行教育影响原则。A.直接体现了“平行教育”的本质，即教育者与个人的关系以集体为中介，集体既是教育对象，也是教育手段。√B.此说法混淆了“平行教育”与“同时教育”。马卡连柯强调的并非教师直接面向个人和集体“同时进行”，而是通过集体间接影响个人。C.此说法涉及自我教育，但并非“平行教育影响原则”的核心要义。D.此说法强调家校合作，属于教育协作范畴，与“平行教育”的集体作用机制无关。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 169}},
  {"id": "kc|edu-principle|ep-08|知识点三|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-08", "chName": "第八章 德育", "sec": "知识点三：德育过程", "no": 1, "q": "德育过程的主要矛盾是（　）", "opts": ["社会的道德要求与学生品德水平的矛盾", "知与不知的矛盾", "德育要求与个人需求的矛盾", "正确思想与错误思想的矛盾"], "a": 0, "exp": "此题考查德育过程的主要矛盾。德育过程的主要矛盾是社会的道德要求与学生品德水平的矛盾。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 169}},
  {"id": "kc|edu-principle|ep-08|知识点三|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-08", "chName": "第八章 德育", "sec": "知识点三：德育过程", "no": 2, "q": "小小明明知道自己不应该偷同学的笔记本，但是却没有控制住自己的行为。针对这种情况，教师选择去纠正小小的不良行为，但并没有进行道德理论知识的说服教育。这种情况体现了德育过程的（　）", "opts": ["间接性", "多开端性", "针对性", "制约性"], "a": 2, "exp": "此题考查德育过程的规律。德育实践具有针对性，指教师应根据知、情、意、行每一要素的规律和特点，采用不同的德育手段和方法，开展具有针对性的教育活动。题干中，小小知道自已的行为是不对的，说明他具有一定的道德认识，所以教师没有再进行理论说教，而是选择纠正小小的不良行为，这体现了德育过程的针对性。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 170}},
  {"id": "kc|edu-principle|ep-08|知识点三|3", "bank": "kc", "subj": "edu-principle", "ch": "ep-08", "chName": "第八章 德育", "sec": "知识点三：德育过程", "no": 3, "q": "“德育过程是自我教育的过程”的核心依据是（　）", "opts": ["德育内容必须完全由学生自主选择", "教师无法直接干预学生的道德成长", "道德发展本质上是主体对价值观的主动建构", "自我教育可以完全替代外部德育"], "a": 2, "exp": "此题考查德育过程的规律。自我教育的本质就是学生对自已的道德建设有了能动性，也叫主动性。A.说法过于片面，将“自我教育”极端化为“自主选择”，忽视了教育的社会性引导作用。实际上德育内容需符合社会主流价值观，并非完全由学生自主选择，老师可以引导学生理解、批判和内化内容。B.说法错误，将“自我教育”曲解为“排斥外部影响”，不符合教育实际。实际上教师可通过创设情境、引导反思等方式干预和促进道德发展，但干预需尊重学生的主体性。C.强调道德发展的内在机制一学生通过主动思考、情感体验和行为实践，将外部道德要求转化为自身的价值认同，这正是“自我教育”作为德育过程本质的理论根基。√D.说法极端，自我教育与外部德育（教师引导、环境熏陶等）是相辅相成的关系，而非替代关系。德育需要外部引导作为起点和支撑，最终通过自我教育实现内化。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 170}},
  {"id": "kc|edu-principle|ep-08|知识点三|4", "bank": "kc", "subj": "edu-principle", "ch": "ep-08", "chName": "第八章 德育", "sec": "知识点三：德育过程", "no": 4, "q": "下列教育现象中不符合德育过程“内化于心、外化于行”的是（　）", "opts": ["小王同学被老师教育后，认识到了错误，不再迟到", "小张同学看了电影《长津湖》后，撰写了一篇1500字的观后感", "小黄同学上了道德与法治课后，过马路时严格遵守交通规则", "小李同学听老师讲了《小猫钓鱼》的故事后，做事情时专心致志"], "a": 1, "exp": "此题考查德育过程。“内化于心、外化于行”是指言行一致、表里如一。A、C、D选项都体现了思想认识和实践行动的结合。B选项中，小张同学在观看电影后撰写的观后感属于道德认知，没有体现相应的行为。此题为选非题，因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 170}},
  {"id": "kc|edu-principle|ep-08|知识点三|5", "bank": "kc", "subj": "edu-principle", "ch": "ep-08", "chName": "第八章 德育", "sec": "知识点三：德育过程", "no": 5, "q": "小红看到同桌摔倒后，不仅没有上前扶，反而嘲笑对方。当老师询问时，她认为“这只是小事，没必要在意”。经过老师的教导，小红知道自已的行为是错误的，但内心毫无波澜，不觉得对方值得同情，再次遇到类似情况时，依旧会冷漠旁观。根据德育过程的规律，对小红进行干预时最适合的切人点是（　）", "opts": ["加强道德认知", "培养道德情感", "训练道德意志", "规范道德行为"], "a": 1, "exp": "此题考查德育过程的规律。A.小红知道自已的行为是错误的，因而小红的问题并非道德认知问题。B.小红“内心毫无波澜，不觉得对方值得同情”，这一表现反映出她存在明显的道德情感缺失。由此可见，小红的核心问题在于她缺乏共情能力，不能体会他人的痛苦。基于此，对小红进行干预时最适合的切人点应是培养道德情感。√C.小红的“冷漠旁观”并非意志薄弱，而是道德情感缺失导致的“不愿为”。D.道德行为需以情感为基础，缺乏情感驱动的行为难以持久，故需先强化情感。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 170}},
  {"id": "kc|edu-principle|ep-08|知识点四|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-08", "chName": "第八章 德育", "sec": "知识点四：德育原则", "no": 1, "q": "苏联教育家马卡连柯提出“平行教育影响”的德育原则是指（　）", "opts": ["知行统一原则", "严格要求与尊重信任相结合原则", "集体教育与个别教育相结合原则", "教育影响的一致性与连续性原则"], "a": 2, "exp": "此题考查集体教育与个别教育相结合原则。德育原则总结表德育原则含义既通过集体教育影响每个成员，又通过个别成员的教育影响集体；既面向集集体教育与个别教育相结合原则体，又因材施教指导学生学习和掌握一定的政治理论和道德伦理，用学到的思想道德准则指导知行统一原则自己的行动正面引导与纪律约束相结合原则以事实、道理、榜样等进行启发诱导，同时制定必要的规章制度进行约束（疏导原则、循循善诱原则）发挥积极因素与克服消极因素相结合原则调动学生自我教育的积极性，依靠和发扬他们自身的积极因素去克服他们品德（长善救失原则）上的消极因素严格要求与尊重信任相结合原则把对学生的思想和品行的严格要求与对他们个人的尊重和信赖结合起来照顾年龄特点与照顾个性特点相结合原则从学生品德发展的实际出发，根据他们的年龄特征和个性差异进行不同的道德（因材施教原则）教育有目的、有计划地把来自各方面对学生的教育影响加以组织、调节，使其互相教育影响的一致性原则配合、协调一致地进行教育在组织、调节中相互协调一致，前后连贯地进行教育影响的连续性原则平行教育影响原则是指教育个人与教育集体的活动应同时进行，每一项针对集体开展的教育活动，应收到既教育集体又教育个人的效果，体现了集体教育与个别教育相结合原则。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 170}},
  {"id": "kc|edu-principle|ep-08|知识点四|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-08", "chName": "第八章 德育", "sec": "知识点四：德育原则", "no": 2, "q": "“一把钥匙开一把锁”体现的德育原则是（　）", "opts": ["教育影响的连续性原则", "发挥积极因素与克服消极因素相结合原则", "教育影响的一致性原则", "照顾年龄特点与照顾个性特点相结合原则"], "a": 3, "exp": "此题考查照顾年龄特点与照顾个性特点相结合原则。“一把钥匙开一把锁”体现了照顾年龄特点与照顾个性特点相结合原则。依据知识点四第1题解析，因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 170}},
  {"id": "kc|edu-principle|ep-08|知识点四|3", "bank": "kc", "subj": "edu-principle", "ch": "ep-08", "chName": "第八章 德育", "sec": "知识点四：德育原则", "no": 3, "q": "高中生小强在课堂上玩手机，下课后，李老师把小强单独叫到办公室，语重心长地谈了课堂上玩手机的不良影响，并告诉小强相信他之后不会再犯这样的错误。从此以后，小强在课堂上再也没有玩过手机了。此处遵循的是德育的（　）", "opts": ["集体教育与个别教育相结合原则", "教育影响的一致性与连续性原则", "严格要求与尊重信任相结合原则", "长善救失原则"], "a": 2, "exp": "此题考查严格要求与尊重信任相结合原则。要求，遵循了严格要求与尊重信任相结合原则。依据知识点四第1题解析，因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 170}},
  {"id": "kc|edu-principle|ep-08|知识点四|4", "bank": "kc", "subj": "edu-principle", "ch": "ep-08", "chName": "第八章 德育", "sec": "知识点四：德育原则", "no": 4, "q": "班主任陈老师通过生杏的酸涩和熟否的香甜来教育一位早恋的初三女生，告诉她谈恋爱和吃杏子是一样的道理，中学生还没有生长成熟，此时若谈恋爱，就如同吃生杏子一般，只能又苦又涩；只有等到成熟后再去品尝，才会香甜可口，无比幸福。就这样，陈老师帮助这位女生从早恋中走了出来。这体现了德育的（　）", "opts": ["知行统一原则", "长善救失原则", "有的放矢原则", "疏导原则"], "a": 3, "exp": "此题考查疏导原则。此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 170}},
  {"id": "kc|edu-principle|ep-08|知识点四|5", "bank": "kc", "subj": "edu-principle", "ch": "ep-08", "chName": "第八章 德育", "sec": "知识点四：德育原则", "no": 5, "q": "深联系微信193163788日某小学一年级班主任李老师为培养学生的独立自主能力，要求学生自已整理书包。于是，每天放学后学生都会独立整理书包。然而，很多家长因“嫌孩子慢”“怕耽误时间”，在家中仍包办代替。一学期后，仅有少数学生能坚持自主整理。这一结果主要是因为违背了（　）", "opts": ["严格要求与尊重信任相结合原则", "集体教育与个别教育相结合原则", "教育影响的一致性原则", "教育影响的连续性原则"], "a": 2, "exp": "此题考查教育影响的一致性原则。A.题干未涉及教师要求过严或不尊重学生的问题。B.题干未涉及针对个别学生的特殊教育措施。C.教育影响的一致性原则强调学校、家庭、社会等教育主体应在目标和方法上协调统一，避免在学生身上施加的教育影响相互抵消。题干中，家长与李老师的做法不一致，导致教育效果被削弱，违背了教育影响的一致性原则。√D.教育影响的连续性原则强调教育应长期、持续地施加影响。题干的关键矛盾是家校要求冲突，而非时间上的中断。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 170}},
  {"id": "kc|edu-principle|ep-08|知识点四|6", "bank": "kc", "subj": "edu-principle", "ch": "ep-08", "chName": "第八章 德育", "sec": "知识点四：德育原则", "no": 6, "q": "学校要求每个年级都要开展“做文明学生”的班会，并要求内容随年龄逐步深化，这体现的德育原则是（　）", "opts": ["长善救失原则", "知行统一原则", "教育影响的一致性原则", "教育影响的连续性原则"], "a": 3, "exp": "此题考查教育影响的连续性原则。在不同年级持续开展同一主题的教育班会，并且内容根据年龄逐步深化，这保证了教育影响的持续递进，符合教育影响的连续性原则。依据知识点四第1题解析，因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 171}},
  {"id": "kc|edu-principle|ep-08|知识点四|7", "bank": "kc", "subj": "edu-principle", "ch": "ep-08", "chName": "第八章 德育", "sec": "知识点四：德育原则", "no": 7, "q": "某学生经常不完成作业，李老师没有直接批评他，而是耐心询问原因，告诉他按时完成作业是学生的基本义务，同时明确要求他今后必须按时完成作业，否则会联系家长共同督促。这体现的德育原则是（　）", "opts": ["教育影响的连续性原则", "教育影响的一致性原则", "正面引导与纪律约束相结合原则", "发挥积极因素与克服消极因素相结合原则"], "a": 2, "exp": "此题考查正面引导与纪律约束相结合原则。李老师没有直接批评学生，而是耐心询问原因，并告知学生按时完成作业是其基本义务，这体现了通过说理和引导的方式帮助学生认识问题。同时，李老师明确提出要求，并说明不按时完成作业可能带来的后果，这体现了纪律的约束作用。依据知识点四第1题解析，因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 171}},
  {"id": "kc|edu-principle|ep-08|知识点四|8", "bank": "kc", "subj": "edu-principle", "ch": "ep-08", "chName": "第八章 德育", "sec": "知识点四：德育原则", "no": 8, "q": "“不以不善而废其善”“要尽量多地要求一个人，也要尽可能多地尊重一个人”分别体现了（　）", "opts": ["①④", "②③", "①③", "②④"], "a": 1, "exp": "此题考查德育原则。长善救失原则，即发挥积极因素与克服消极因素相结合原则，“一分为二”地看待学生，通过发扬学生的优点来克服其缺点。“要尽量多地要求一个人，也要尽可能多地尊重一个人”体现了严格要求与尊重信任相结合原则，即严慈相济原则。依据知识点四第1题解析，因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 171}},
  {"id": "kc|edu-principle|ep-08|知识点五|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-08", "chName": "第八章 德育", "sec": "知识点五：德育方法", "no": 1, "q": "班内某学生乱丢垃圾，不管走到哪，不管谁的位置，想扔就扔。老师提醒该同学要把教室当成自已的卧室，如果别人都在你的卧室乱丢垃圾，你是什么心情呢？该教师的做法运用了下列哪种德育方法？（　）", "opts": ["移情", "团体公正法", "角色扮演法", "情境模拟法"], "a": 0, "exp": "此题考查德育方法。移情是指对事物进行判断和决策之前，将自已处在他人位置考虑他人的心理反应，理解他人的态度和情感的能力。题干中，教师请乱丢垃圾的学生站在别人的角度考虑，属于移情。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 171}},
  {"id": "kc|edu-principle|ep-08|知识点五|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-08", "chName": "第八章 德育", "sec": "知识点五：德育方法", "no": 2, "q": "一天，孙老师在楼下散步，两个孩子在摇一棵新栽的小树，一位街道阿姨正高声训斥他们，可孩子们却做着鬼脸继续摇。孙老师看在眼里，他走上去，抱着小树，把耳朵贴在小树上，装作认真听的样子，都要折了，它让我告诉你们别摇了，等它长大了好给你们遮阴凉，行吗？”“行！”两个孩子高高兴兴地走了。孙老师使用的是（　）", "opts": ["说服教育法", "情感陶冶法", "实践锻炼法", "自我教育法"], "a": 0, "exp": "此题考查德育方法。德育方法总结表含义方法通过对学生摆事实、讲道理，经过思想情感上的沟通与互动，让学生认识道理的真谛并自觉践行说服教育通过创设良好的教育情境，对学生进行积极感化和熏陶，潜移默化地培养学生品德情境陶冶有目的地组织学生进行一定的实践活动，以培养他们的良好品德实践锻炼在教师的引导下，学生经过自觉学习、自我反思和自我改进，使自身品德不断完善自我教育（自我修养）以他人的高尚品德、模范行为和卓越成就来影响学生品德榜样示范对学生的品德水平给予肯定或否定的评价，以促进学生发扬优点、克服缺点，逐步培养其良好品德评价品德奖赏是对学生突出的优秀品行做出较高的评价；惩罚是对学生所犯错误的处理奖赏与惩罚案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 171}},
  {"id": "kc|edu-principle|ep-08|知识点五|3", "bank": "kc", "subj": "edu-principle", "ch": "ep-08", "chName": "第八章 德育", "sec": "知识点五：德育方法", "no": 3, "q": "小明在班级里担任卫生委员一职，期末结束时，班主任在小明的评价表上留下这样一段文字：这学期作为卫生委员，辛苦你了，每天都督促好值日生工作，老师真的很感谢你！你积极肯学，认真对待每一件事情，看你的作业，真的让我赏心悦目！老师想给你提个建议，在学习中，要多思多问，工作中再大胆些，发挥潜力，上课大胆举手发言，课外多阅读书籍，拓宽知识面，向同学们展示你的能力！老师的这段文字属于（　）", "opts": ["品德评价法", "说服教育法", "榜样示范法", "情感陶冶法"], "a": 0, "exp": "此题考查德育方法。评价法。依据知识点五第2题解析，因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 171}},
  {"id": "kc|edu-principle|ep-08|知识点五|4", "bank": "kc", "subj": "edu-principle", "ch": "ep-08", "chName": "第八章 德育", "sec": "知识点五：德育方法", "no": 4, "q": "在新冠疫情防控期间，高中生张阳主动担任社区志愿者，为人们提供贴心的服务与帮助，学校教师得（　）", "opts": ["自我教育法", "情感陶冶法", "榜样示范法", "奖惩法"], "a": 3, "exp": "此题考查德育方法。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 171}},
  {"id": "kc|edu-principle|ep-08|知识点五|5", "bank": "kc", "subj": "edu-principle", "ch": "ep-08", "chName": "第八章 德育", "sec": "知识点五：德育方法", "no": 5, "q": "“与善人居，如人芝兰之家，久而自芳也；与恶人居，如人鲍鱼之肆，久而自臭也。”这句话体现的德育方法是（　）", "opts": ["榜样示范法", "情境陶冶法", "实践锻炼法", "品德评价法"], "a": 1, "exp": "此题考查德育方法。则会像待在咸鱼店一样染上臭味。这是潜移默化的过程。依据知识点五第2题解析，这属于情境陶冶法。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 172}},
  {"id": "kc|edu-principle|ep-08|知识点五|6", "bank": "kc", "subj": "edu-principle", "ch": "ep-08", "chName": "第八章 德育", "sec": "知识点五：德育方法", "no": 6, "q": "孟子日：“天将降大任于斯人也，必先苦其心志，劳其筋骨，饿其体肤，空乏其身，行拂乱其所为。”这体现了（　）", "opts": ["实践锻炼法", "自我教育法", "品德评价法", "奖惩法"], "a": 0, "exp": "此题考查德育方法。能力都得到提高。依据知识点五第2题解析，这句话体现了实践锻炼法。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 172}},
  {"id": "kc|edu-principle|ep-08|知识点五|7", "bank": "kc", "subj": "edu-principle", "ch": "ep-08", "chName": "第八章 德育", "sec": "知识点五：德育方法", "no": 7, "q": "下列格言中不能体现自我教育法的是（　）", "opts": ["吾日三省吾身", "内省不疚，何恤人言", "见贤思齐焉，见不贤而内自省也", "纸上得来终觉浅，绝知此事要躬行"], "a": 3, "exp": "此题考查德育方法。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 172}},
  {"id": "kc|edu-principle|ep-08|知识点五|8", "bank": "kc", "subj": "edu-principle", "ch": "ep-08", "chName": "第八章 德育", "sec": "知识点五：德育方法", "no": 8, "q": "下列古语中所体现的德育方法与“桃李不言，下自成蹊”一致的是（　）", "opts": ["奖善而惩恶，先王之治也", "纸上得来终觉浅，绝知此事要躬行", "其身正，不令而行；其身不正，虽令不从", "夫子循循然善诱人，博我以文，约我以礼，欲罢不能"], "a": 2, "exp": "此题考查德育方法。A.“奖善而惩恶，先王之治也”体现的是品德评价法，即强调通过奖励和惩罚来对学生的品德行为进行评价和引导。B.“纸上得来终觉浅，绝知此事要躬行”体现的是实践锻炼法，即强调通过亲身实践来获取知识和培养品德。C.“其身正，不令而行；其身不正，虽令不从”意思是当管理者自身端正，做出表率时，不用下命令，被管理者也会跟着行动起来；反之，纵然三令五申，被管理者也不会服从。与“桃李不言，下自成蹊”一样，都强调自身行为示范的重要性，属于榜样示范法。√D.“夫子循循然善诱人，博我以文，约我以礼，欲罢不能”体现的是说服教育法，即强调教育者要善于引导学生，通过知识和礼仪来教育学生。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 172}},
  {"id": "kc|edu-principle|ep-08|知识点六|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-08", "chName": "第八章 德育", "sec": "知识点六：德育途径", "no": 1, "q": "班主任谈话与工作属于下列哪一种途径？（　）", "opts": ["直接教育", "教学育人", "管理育人", "指导育人"], "a": 3, "exp": "此题考查德育途径。班主任谈话与工作属于间接教育中的指导育人。因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 172}},
  {"id": "kc|edu-principle|ep-08|知识点六|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-08", "chName": "第八章 德育", "sec": "知识点六：德育途径", "no": 2, "q": "在某中学地理课堂上，地理老师通过展示海洋环境污染有关的视频，引导学生辩证思考人类过度活动对生态环境的破坏，从而培养学生的环保意识。该教师采用的德育途径是（　）", "opts": ["指导育人", "学科育人", "环境育人", "活动育人"], "a": 1, "exp": "此题考查德育途径。德育途径分为直接与间接两种。直接的德育途径是指通过开设专门的德育课程（如思想品德课等），系驼套课程公众号【研大]统地向学生传授道德知识和道德理论。间接的德育途径是指在其他学科教学或教育实践活动中，通过道德渗透的方式，潜移默化地引导学生形成和掌握道德观念与道德知识。题干中，地理老师在课堂教学中引导学生思考环境保护的问题，是以学科育人的方式对学生进行道德渗透。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 172}},
  {"id": "kc|edu-principle|ep-08|知识点六|3", "bank": "kc", "subj": "edu-principle", "ch": "ep-08", "chName": "第八章 德育", "sec": "知识点六：德育途径", "no": 3, "q": "宿管老师每天检查宿舍卫生和安全情况，督促学生整理内务，以保持良好的宿舍环境；同时，关注学生的生活习惯和人际关系，及时发现并解决学生之间的矛盾。通过这些工作来培养学生的生活自理能力、卫生习惯和团队合作精神。从德育途径来看，这属于（　）", "opts": ["指导育人", "环境育人", "活动育人", "管理育人"], "a": 3, "exp": "此题考查德育途径。习惯和团队合作精神，符合德育途径中管理育人的特点。因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 172}},
  {"id": "kc|edu-principle|ep-08|知识点六|4", "bank": "kc", "subj": "edu-principle", "ch": "ep-08", "chName": "第八章 德育", "sec": "知识点六：德育途径", "no": 4, "q": "《中小学德育工作指南》指出，要充分发挥课堂教学的主渠道作用，将中小学德育内容细化落实到各学科课程的教学目标之中，融人渗透到教育教学全过程。这体现的德育途径是（　）", "opts": ["教学育人", "指导育人", "环境育人", "全方位育人"], "a": 0, "exp": "此题考查德育途径。A.教学育人是发挥道德课程以外的其他课程的德育功能。“将中小学德育内容细化落实到各学科课程的教学目标之中”体现的是教学育人。√B.指导育人是通过各种形式的指导进行德育，如班主任谈话与工作、职业指导、就业讲座等。C.环境育人是加强校园文化建设，使环境和文化相结合，发挥校园环境育人的作用，如优化校园环境、营造文化氛围等。D.全方位育人是教师的德育活动并不仅仅存在于课堂之中，更存在于日常生活之中，即直接德育与间接德育相结合，全方位地促进学生品德的发展。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 172}},
  {"id": "kc|edu-principle|ep-09|知识点一|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-09", "chName": "第九章 教师与学生", "sec": "知识点一：教师的概念与分类", "no": 1, "q": "下列哪一项最准确地描述了教师的根本含义？（　）", "opts": ["在学校工作的专职人员", "从事知识传授并促进学习者发展的专业人员", "拥有教师资格证书的从业者", "负责班级管理的学生监督者"], "a": 1, "exp": "此题考查教师的概念。教师的根本含义不仅仅指其在特定场所（如学校）工作或持有证书，其核心在于专业性与目的性一—通过教育实践活动，系统性地传授知识、技能，并促进学生的全面发展。A、C、D选项均只描述了教师的某一特征或局部职能，未能涵盖其本质。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 173}},
  {"id": "kc|edu-principle|ep-09|知识点一|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-09", "chName": "第九章 教师与学生", "sec": "知识点一：教师的概念与分类", "no": 2, "q": "负责学校课程开发、教学研究与教师专业发展指导的教师通常是（　）", "opts": ["班主任", "教研员", "辅导员", "教务干事"], "a": 1, "exp": "B理解题此题考查教师的分类。教研员（或教研组长）的核心职责是课程开发、教学研究与教师专业发展指导。班主任侧重班级管理，辅导员聚焦学生事务，教务干事负责教学行政，三者均不以此为核心职能。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 173}},
  {"id": "kc|edu-principle|ep-09|知识点二|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-09", "chName": "第九章 教师与学生", "sec": "知识点二：教师劳动的特点", "no": 1, "q": "学生向师性和模仿性的心理特征决定了教师劳动具有（　）", "opts": ["强烈的示范性", "独特的创造性", "空间的广延性", "时间的连续性"], "a": 0, "exp": "此题考查教师劳动的特点。学生向师性和模仿性的心理特征决定了教师劳动具有强烈的示范性。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 173}},
  {"id": "kc|edu-principle|ep-09|知识点二|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-09", "chName": "第九章 教师与学生", "sec": "知识点二：教师劳动的特点", "no": 2, "q": "“十年树木，百年树人”这句话说明了教师劳动的（　）", "opts": ["创造性", "复杂性", "示范性", "长期性"], "a": 3, "exp": "此题考查教师劳动的特点。“十年树木，百年树人”说明对年轻一代的培养不是一朝一夕就能完成的，而是长期教育的结果。十年与百年都是表示时间长度的数量词，指代教师劳动的长期性。因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 173}}
]);
